# Note: This script loads the pre-cleaned data generated by data-cleaning.R,
# eliminating redundant preprocessing steps.
#
# Generates all three figures in /figures/
#
# Alternatively, run individual scripts:
#   - scripts/eda-weekly-sales-yoy.R
#   - scripts/eda-correlation-matrix.R
#   - scripts/eda-sales-by-size.R

library(tidyverse)
library(lubridate)
library(scales)

# Load Pre-Cleaned Training Data
clean_path <- file.path("data", "clean", "train_merged_clean.rds")
if (!file.exists(clean_path)) {
  stop("Cleaned data not found. Please run scripts/data-cleaning.R first.")
}

message("Loading cleaned training data from data/clean/train_merged_clean.rds...")
train_clean <- readRDS(clean_path)

fig_dir <- "figures"
if (!dir.exists(fig_dir)) {
  dir.create(fig_dir, recursive = TRUE)
}

# Figure 1: WEEKLY SALES BY YEAR LAYERED
message("Generating Figure 1: Total Weekly Sales by Year...")
weekly_sales_layered <- train_clean %>%
  group_by(Date, Year) %>%
  summarise(Total_Sales = sum(Weekly_Sales), .groups = "drop") %>%
  mutate(
    Aligned_Date = make_date(year = 2000L, month = month(Date), day = day(Date)),
    Year_Factor  = factor(Year)
  )

p1 <- ggplot(weekly_sales_layered, aes(x = Aligned_Date, y = Total_Sales, color = Year_Factor, group = Year_Factor)) +
  geom_line(linewidth = 0.8) +
  scale_x_date(date_breaks = "1 month", date_labels = "%b") +
  scale_y_continuous(labels = scales::dollar) +
  labs(
    title = "Total Weekly Sales by Year",
    x = "Month",
    y = "Total Weekly Sales",
    color = "Year"
  ) +
  theme_minimal()

print(p1)
ggsave(file.path(fig_dir, "weekly-sales-YoY.png"), plot = p1, width = 8, height = 6, dpi = 300)

# Figure 2: FEATURE CORRELATION MATRIX
message("Generating Figure 2: Feature Correlation Matrix...")
cor_data <- train_clean %>%
  select(Weekly_Sales, Size, CPI, Unemployment, Temperature, Fuel_Price, starts_with("MarkDown"))

cor_matrix <- cor(cor_data, use = "complete.obs")
cor_long <- cor_matrix %>%
  as.data.frame() %>%
  rownames_to_column(var = "Var1") %>%
  pivot_longer(-Var1, names_to = "Var2", values_to = "Correlation")

p2 <- ggplot(cor_long, aes(x = Var1, y = Var2, fill = Correlation)) +
  geom_tile(color = "white") +
  scale_fill_gradient2(
    low = "blue", high = "red", mid = "white",
    midpoint = 0, limit = c(-1, 1), space = "Lab",
    name = "Correlation"
  ) +
  theme_minimal() +
  theme(
    axis.text.x = element_text(angle = 45, vjust = 1, hjust = 1, size = 10),
    axis.text.y = element_text(size = 10)
  ) +
  coord_fixed() +
  labs(title = "Feature Correlation Matrix", x = "", y = "")

print(p2)
ggsave(file.path(fig_dir, "feature-correlation-matrix.png"), plot = p2, width = 8, height = 6, dpi = 300)

# Figure 3: STORE SIZE VS MEAN WEEKLY SALES BY STORE TYPE
message("Generating Figure 3: Store Size vs. Mean Weekly Sales by Store Type...")
store_summary <- train_clean %>%
  group_by(Store, Type, Size) %>%
  summarise(mean_sales = mean(Weekly_Sales, na.rm = TRUE), .groups = "drop")

p3 <- ggplot(store_summary, aes(x = Size, y = mean_sales, color = Type)) +
  geom_point(size = 2.5, alpha = 0.85) +
  geom_smooth(method = "lm", se = FALSE, linetype = "dashed", linewidth = 0.7) +
  scale_y_continuous(labels = label_number(scale_cut = cut_short_scale())) +
  labs(
    title = "Store Size vs. Mean Weekly Sales by Store Type",
    x = "Store Size (sq ft)",
    y = "Mean Weekly Sales",
    color = "Type"
  ) +
  theme_minimal()

print(p3)
ggsave(file.path(fig_dir, "avg-weekly-sales-by-size.png"), plot = p3, width = 8, height = 6, dpi = 300)

message("All figures generated and saved to /figures/ successfully!")